-- MANUAL ONLY. Review and authorize before execution. No Storage objects created.
-- Requires public.cursos and public.usuarios. UUIDs are generated by JPA.
-- Intentionally fails if already applied: do not silently accept a divergent schema.
BEGIN;
SET LOCAL lock_timeout = '5s';
CREATE TABLE public.curso_modulos (
    id UUID PRIMARY KEY,
    curso_id UUID NOT NULL REFERENCES public.cursos(id) ON DELETE RESTRICT,
    titulo VARCHAR(150) NOT NULL CHECK (length(btrim(titulo)) > 0),
    orden INTEGER NOT NULL CHECK (orden > 0)
);
CREATE INDEX curso_modulos_curso_orden_idx ON public.curso_modulos(curso_id, orden, id);
CREATE TABLE public.curso_materiales (
    id UUID PRIMARY KEY,
    modulo_id UUID NOT NULL REFERENCES public.curso_modulos(id) ON DELETE RESTRICT,
    titulo VARCHAR(200) NOT NULL CHECK (length(btrim(titulo)) > 0),
    object_key VARCHAR(500) NOT NULL UNIQUE CHECK (length(btrim(object_key)) > 0),
    nombre_original VARCHAR(255) NOT NULL CHECK (length(btrim(nombre_original)) > 0),
    mime_type VARCHAR(100) NOT NULL,
    tamano_bytes BIGINT NOT NULL CHECK (tamano_bytes BETWEEN 1 AND 10485760),
    tipo VARCHAR(10) NOT NULL CHECK (tipo IN ('PDF', 'DOCX', 'PPTX', 'ZIP')),
    estado VARCHAR(30) NOT NULL DEFAULT 'PENDIENTE'
        CHECK (estado IN ('PENDIENTE', 'ACTIVO', 'ELIMINACION_PENDIENTE')),
    creado_por UUID NOT NULL REFERENCES public.usuarios(id) ON DELETE RESTRICT,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK ((tipo = 'PDF' AND mime_type = 'application/pdf')
        OR (tipo = 'DOCX' AND mime_type = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document')
        OR (tipo = 'PPTX' AND mime_type = 'application/vnd.openxmlformats-officedocument.presentationml.presentation')
        OR (tipo = 'ZIP' AND mime_type = 'application/zip'))
);
CREATE INDEX curso_materiales_modulo_estado_idx ON public.curso_materiales(modulo_id, estado, created_at, id);
-- No public API policies: only trusted backend DB connections may access metadata.
-- Verify the backend DB role can operate under RLS before deployment.
ALTER TABLE public.curso_modulos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.curso_materiales ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.curso_modulos, public.curso_materiales FROM PUBLIC;
-- Supabase roles are optional for compatibility with an isolated PostgreSQL test DB.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
        REVOKE ALL ON public.curso_modulos, public.curso_materiales FROM anon;
    END IF;
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
        REVOKE ALL ON public.curso_modulos, public.curso_materiales FROM authenticated;
    END IF;
END $$;
COMMIT;
